INSERT INTO MasterLibrary_PackageAliases(PackageId,Alias,AliasType,Source) SELECT Id,'SO-8','JEDEC','IC seed 021' FROM PackageDefinition WHERE PackageName='SO08P127W078' AND NOT EXISTS(SELECT 1 FROM MasterLibrary_PackageAliases a WHERE a.PackageId=PackageDefinition.Id AND lower(a.Alias)=lower('SO-8'));
